// Convert Planner stages dictionary to array format
// Maps planner Worker1/Worker2 to actual spawned worker names

const input = $input.first().json.body;
const stages = input.stages;
const sessionId = input.sessionId;
const workers = input.workers || [];

console.log(`🚀 Starting stage conversion for session: ${sessionId}`);

if (!stages || typeof stages !== 'object') {
  throw new Error('No stages found');
}

if (!workers || workers.length === 0) {
  throw new Error('No workers found');
}

// ===== Build simple worker lookup by index =====
const workersByIndex = {};
workers.forEach((w, idx) => {
  workersByIndex[idx] = {
    name: w.workerName,
    port: w.port
  };
  console.log(`Worker ${idx}: ${w.workerName} on port ${w.port}`);
});

// ===== Convert stages =====
const stagesArray = [];

// Process each stage in numeric order
const stageKeys = Object.keys(stages).sort((a, b) => parseInt(a) - parseInt(b));

stageKeys.forEach(stageKeyStr => {
  const stageNum = parseInt(stageKeyStr);
  const stage = stages[stageKeyStr];

  console.log(`\nProcessing Stage ${stageNum}: ${stage.stageTitle}`);

  const tasks = [];
  let workerIdx = 0;

  // Direct iteration - only process objects that have required fields
  for (const key in stage) {
    const taskData = stage[key];

    // Skip metadata - these have simple values, not objects with coordinates
    if (!taskData || typeof taskData !== 'object' || !taskData.coordinates) {
      continue;
    }

    // This is a worker task
    const actualWorker = workersByIndex[workerIdx];
    if (!actualWorker) {
      console.warn(`No worker at index ${workerIdx}`);
      continue;
    }

    console.log(`  Task ${key} → ${actualWorker.name} (port ${actualWorker.port})`);

    tasks.push({
      sessionId: sessionId,
      stageNumber: stageNum,
      worker: actualWorker.name,
      port: actualWorker.port,
      taskPrompt: taskData.fullPrompt || '',
      coordinates: taskData.coordinates,
      status: taskData.status || 'queued'
    });

    workerIdx++;
  }

  stagesArray.push({
    stageNumber: stageNum,
    stageTitle: stage.stageTitle,
    status: stage.status || 'not-started',
    taskCount: tasks.length,
    tasks: tasks
  });
});

console.log(`\n✅ Conversion complete: ${stagesArray.length} stages`);

return { 
  stagesArray: stagesArray,
  totalStages: stagesArray.length,
  sessionId: sessionId,
  workerCount: workers.length
};

// Get stage number from current loop item
const currentStage = $('Loop Over Items').first().json.stageNumber;
const previousStage = currentStage - 1;
const sessionId = $input.first().json.sessionId;

if (currentStage === 1) {
  return {
    sessionId: sessionId,
    stageNumber: 1, 
    canProceed: true,
    reason: "First stage"
  };
}

// Now get the document (must come from previous MongoDB read or Set node)
const doc = $input.first().json;

if (!doc.stages || !doc.stages[previousStage]) {
  return {
    stageNumber: currentStage,
    canProceed: false,
    reason: `Stage ${previousStage} not found`
  };
}

const previousStageData = doc.stages[previousStage];
const workers = Object.keys(previousStageData.tasks);

//const allComplete = workers.every(w => 
//  previousStageData.tasks[w].status === "completed"
//);
const allComplete = previousStageData.status === "completed";

return {
  sessionId: sessionId,
  canProceed: allComplete,
  previousStage: previousStage,
  stageNumber: currentStage,
  completedWorkers: workers.filter(w => previousStageData.tasks[w].status === "completed").length,
  totalWorkers: workers.length
};
